PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE guestbook (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, note TEXT, badge TEXT DEFAULT 'Founding Visitor', signed_at TEXT);
CREATE TABLE visits (id INTEGER PRIMARY KEY AUTOINCREMENT, page TEXT, referrer TEXT, visited_at TEXT);
CREATE TABLE presets (short_id TEXT PRIMARY KEY, payload TEXT NOT NULL, created_at TEXT NOT NULL);
DELETE FROM sqlite_sequence;
